import torch
WIDTH = 4
class Model(torch.nn.Module):
    def forward(self, h):
        return h.view(-1, WIDTH)

import torch
WIDTH = 4
class Model(torch.nn.Module):
    def forward(self, h):
        return torch.reshape(input=h, shape=(-1, WIDTH))

import torch
WIDTH = 4
class Model(torch.nn.Module):
    def forward(self, h):
        return h.view(h.shape[0], WIDTH)

import torch
WIDTH = 4
class Model(torch.nn.Module):
    def forward(self, h):
        return h.view(h.size(0), WIDTH)

import torch
WIDTH = 4
class Model(torch.nn.Module):
    def forward(self, h):
        return h.view(*(-1, WIDTH))
